module:
"""Small library catalogue helpers."""
import csv
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional


@dataclass
class Book:
    code: str
    title: str
    author: str
    copies: int = 1
    loaned: int = 0


def load_books(path: str) -> Dict[str, Book]:
    books: Dict[str, Book] = {}
    with open(path, newline='') as handle:
        for row in csv.DictReader(handle):
            book = Book(row['code'], row['title'], row['author'], int(row.get('copies') or 1))
            books[book.code] = book
    return books


def find_book(books: Dict[str, Book], code: str) -> Optional[Book]:
    return books.get(code.strip().upper())


def lend(books: Dict[str, Book], code: str) -> bool:
    book = find_book(books, code)
    if book is None or book.loaned >= book.copies:
        return False
    book.loaned += 1
    return True


def give_back(books: Dict[str, Book], code: str) -> bool:
    book = find_book(books, code)
    if book is None or book.loaned == 0:
        return False
    book.loaned -= 1
    return True


def available(books: Iterable[Book]) -> List[Book]:
    return [b for b in books if b.loaned < b.copies]


def by_author(books: Iterable[Book], author: str) -> List[Book]:
    key = author.casefold()
    return sorted((b for b in books if b.author.casefold() == key), key=lambda b: b.title)


def save_books(path: str, books: Dict[str, Book]) -> None:
    with open(path, 'w', newline='') as handle:
        writer = csv.writer(handle)
        writer.writerow(['code', 'title', 'author', 'copies'])
        for book in books.values():
            writer.writerow([book.code, book.title, book.author, book.copies])
